oracle_tests:
assert chunks([1], 5) == [[1]]
assert chunks(list(range(5)), 1) == [[0],[1],[2],[3],[4]]
for n in [0,-1]:
    try:
        chunks([1,2], n)
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

v=[9,1,5,3]
assert median(v) == 4
assert v == [9,1,5,3]
assert median([-5]) == -5
try:
    median([])
except ValueError:
    pass
else:
    raise AssertionError('expected ValueError')

for s in [' YES ', '1', 'True']:
    assert parse_bool(s) is True
for s in [' NO ', '0', 'False']:
    assert parse_bool(s) is False
for s in ['', 'maybe']:
    try:
        parse_bool(s)
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')
